1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"strings"
7		"testing"
8	
9		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
10	)
11	
12	func TestCLISuccess(t *testing.T) {
13		input := `{
14		  "currentTerm": 2,
15		  "committedIndex": 1,
16		  "log": [{"index": 1, "term": 2, "command": "a"}],
17		  "requests": [
18		    {"term": 2, "prevLogIndex": 1, "prevLogTerm": 2, "entries": [
19		      {"index": 2, "term": 2, "command": "b"}
20		    ], "leaderCommit": 2}
21		  ]
22		}`
23		var stdout, stderr bytes.Buffer
24		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
25		if code != 0 {
26			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
27		}
28		var out mevwatch.ReplicateOutput
29		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
30			t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
31		}
32		if len(out.Results) != 1 || !out.Results[0].Accepted {
33			t.Fatalf("unexpected results: %+v", out.Results)
34		}
35		if out.FinalCommittedIndex != 2 || len(out.FinalLog) != 2 {
36			t.Fatalf("unexpected final state: %+v", out)
37		}
38	}
39	
40	func TestCLIEmptyInput(t *testing.T) {
41		// 无请求、无日志：输出可解析，results 为空数组而不是 null。
42		var stdout, stderr bytes.Buffer
43		code := runReplicateIO(strings.NewReader(`{}`), &stdout, &stderr)
44		if code != 0 {
45			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
46		}
47		body := strings.TrimSpace(stdout.String())
48		if !strings.Contains(body, `"results": []`) {
49			t.Fatalf("empty results should serialize as [], got: %s", body)
50		}
51		if !strings.Contains(body, `"finalLog": []`) {
52			t.Fatalf("empty log should serialize as [], got: %s", body)
53		}
54	}
55	
56	func TestCLIApplyKV(t *testing.T) {
57		input := `{
58		  "currentTerm": 1,
59		  "committedIndex": 1,
60		  "log": [{"index": 1, "term": 1, "command": "set x=1"}],
61		  "applyKV": true,
62		  "requests": [
63		    {"term": 1, "prevLogIndex": 1, "prevLogTerm": 1, "entries": [
64		      {"index": 2, "term": 1, "command": "set y=a b=c"},
65		      {"index": 3, "term": 1, "command": "delete x"}
66		    ], "leaderCommit": 3}
67		  ]
68		}`
69		var stdout, stderr bytes.Buffer
70		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
71		if code != 0 {
72			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
73		}
74		body := stdout.String()
75		for _, fragment := range []string{
76			`"appliedIndex": 3`,
77			`"applyError": null`,
