144	// TestKVIncrSameTermConflictRejectsWholeRequest 回归保障两种冲突的区分：冲突
145	// 位置的索引与任期都与旧条目相同（idx2 仍是任期 1）、只是命令改为
146	// incr count=-3 时，必须按现有同任期命令冲突拒绝整个请求——不能借任期冲突
147	// 替换提交旧后缀，也不能应用新命令。日志（含未提交的 incr count=100 与
148	// incr count=1.5）、计数 "10"、提交位置 1 与应用位置 1 全部保持原样；请求
149	// 携带的较高任期 3 仍按现有规则保留，且拒绝不附带 conflict。
150	func TestKVIncrSameTermConflictRejectsWholeRequest(t *testing.T) {
151		initial := incrSuffixConflictInitial()
152		out := runKV(t, initial,
153			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
154				Entries: []LogEntry{
155					entry(2, 1, "incr count=-3"), // 与旧 idx2 同任期、不同命令：拒绝
156					entry(3, 3, "set other=x"),
157				}},
158		)
159		result := out.Results[0]
160		if result.Accepted || result.Reason != ReasonCommandConflictSameTerm {
161			t.Fatalf("expected same-term command conflict rejection, got %+v", result)
162		}
163		if result.Conflict != nil {
164			t.Fatalf("command conflict must not carry a conflict hint: %+v", result.Conflict)
165		}
166		if result.Term != 3 {
167			t.Fatalf("higher request term must survive the rejection, term = %d, want 3", result.Term)
168		}
169		if result.CommittedIndex != 1 {
170			t.Fatalf("commit moved on rejection: %d, want 1", result.CommittedIndex)
171		}
172		if got := appliedIndexOf(t, result); got != 1 {
173			t.Fatalf("result appliedIndex = %d, want 1", got)
174		}
175		if result.ApplyError != nil {
176			t.Fatalf("rejected commands must not produce an apply error: %+v", result.ApplyError)
177		}
178	
179		// 原子拒绝：日志、提交位置、应用位置、键值表全部保持请求前状态。
180		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
181			t.Fatalf("log changed after rejection: %+v", out.FinalLog)
182		}
183		if out.FinalTerm != 3 || out.FinalCommittedIndex != 1 {
184			t.Fatalf("final state = term %d ci %d, want term 3 ci 1",
185				out.FinalTerm, out.FinalCommittedIndex)
186		}
187		if *out.FinalAppliedIndex != 1 {
188			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
189		}
190		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "10"}) {
191			t.Fatalf("final kv = %v, want only count=10 (old suffix not committed, new incr not applied)", kv)
192		}
193		if out.FinalApplyError != nil {
194			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
195		}
196	
197		// 输出约定：该拒绝的 JSON 中不出现 conflict 键（注意拒绝原因文本本身含
198		// "entry conflict"，因此按键名 "conflict" 判断）；被拒命令
199		// incr count=-3 也不应出现在最终输出里（finalLog 仍是旧日志，结果对象不含命令）。
200		encoded, err := json.Marshal(out)
201		if err != nil {
202			t.Fatal(err)
203		}
204		body := string(encoded)
205		if strings.Contains(body, `"conflict"`) {
206			t.Fatalf("command-conflict rejection JSON must omit conflict key: %s", body)
207		}
208		if strings.Contains(body, "incr count=-3") || strings.Contains(body, "set other=x") {
209			t.Fatalf("rejected entries leaked into output: %s", body)
210		}
211	}
