213	// TestKVIncrTermConflictBadDeltaOnlyFailsApplication 回归保障第二种区分：不同
214	// 任期的替换本身合法（idx2 旧任期 1、新任期 3），但新增量不是整数
215	// （incr count=x）时，复制与提交照常成功（请求接受、提交位置到 2、最终日志
216	// 完成替换，旧后缀 incr count=100 与 incr count=1.5 消失）；只有提交后的应用
217	// 报告错误——appliedIndex 停在出错条目前的 1，applyError 指向 idx2 且原因为
218	// incr delta 非法，计数保留此前的 "10"，出错条目之后的命令均不存在故不生效。
219	func TestKVIncrTermConflictBadDeltaOnlyFailsApplication(t *testing.T) {
220		initial := incrSuffixConflictInitial()
221		out := runKV(t, initial,
222			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2,
223				Entries: []LogEntry{entry(2, 3, "incr count=x")}},
224		)
225		result := out.Results[0]
226		if !result.Accepted || result.Reason != ReasonOK {
227			t.Fatalf("replication of the legal replacement must succeed: %+v", result)
228		}
229		if result.Term != 3 || result.CommittedIndex != 2 {
230			t.Fatalf("result state = term %d ci %d, want term 3 ci 2",
231				result.Term, result.CommittedIndex)
232		}
233		if got := appliedIndexOf(t, result); got != 1 {
234			t.Fatalf("result appliedIndex = %d, want 1 (stopped before bad new entry)", got)
235		}
236		if result.ApplyError == nil || result.ApplyError.Index != 2 ||
237			result.ApplyError.Reason != ApplyReasonIncrBadDelta {
238			t.Fatalf("result applyError = %+v, want index 2 bad delta", result.ApplyError)
239		}
240	
241		// 复制层面替换仍然完成：旧后缀两条消失，换成新的非法增量条目。
242		wantLog := []LogEntry{
243			entry(1, 1, "incr count=10"),
244			entry(2, 3, "incr count=x"),
245		}
246		if !reflect.DeepEqual(out.FinalLog, wantLog) {
247			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
248		}
249		if out.FinalTerm != 3 || out.FinalCommittedIndex != 2 {
250			t.Fatalf("final state = term %d ci %d, want term 3 ci 2",
251				out.FinalTerm, out.FinalCommittedIndex)
252		}
253		if *out.FinalAppliedIndex != 1 {
254			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
255		}
256		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "10"}) {
257			t.Fatalf("final kv = %v, want only count=10 (discarded +100 must not count, bad new incr unchanged)", kv)
258		}
259		if out.FinalApplyError == nil || out.FinalApplyError.Index != 2 ||
260			out.FinalApplyError.Reason != ApplyReasonIncrBadDelta {
261			t.Fatalf("final applyError = %+v, want index 2 bad delta", out.FinalApplyError)
262		}
263	}
