301	// overflowSuffixInitial 是“应用因 incr 溢出停住 × 任期冲突替换未提交后缀”
302	// 回归场景共享的初始状态：当前任期 1，索引 1..3 任期均为 1，提交位置为 2。
303	// idx1 set count=MaxInt64 已提交生效，计数保存为最大整数的字符串值；idx2
304	// incr count=1 已提交，但 MaxInt64+1 超出有符号 64 位整数范围，应用停在 1、
305	// 首个错误指向 idx2；idx3 incr count=-1 是尚未提交的旧后缀，它绝不能提前把
306	// 计数减回合法值来消除这个错误。
307	func overflowSuffixInitial() InitialState {
308		return InitialState{CurrentTerm: 1, CommittedIndex: 2, Log: []LogEntry{
309			entry(1, 1, "set count="+strconv.FormatInt(math.MaxInt64, 10)),
310			entry(2, 1, "incr count=1"),
311			entry(3, 1, "incr count=-1"),
312		}}
313	}
314	
315	// wantOverflowErrorAtIdx2 断言某条请求结果仍保留 idx2 的同一个溢出错误、应用
316	// 位置停在 1：后缀替换或请求被拒都不能清掉第一次错误，也不能让应用继续。
317	func wantOverflowErrorAtIdx2(t *testing.T, where string, r AppendResult) {
318		t.Helper()
319		if got := appliedIndexOf(t, r); got != 1 {
320			t.Fatalf("%s: appliedIndex = %d, want 1 (application must stay stuck)", where, got)
321		}
322		if r.ApplyError == nil || r.ApplyError.Index != 2 ||
323			r.ApplyError.Reason != ApplyReasonIncrOverflow {
324			t.Fatalf("%s: applyError = %+v, want index 2 %q", where, r.ApplyError, ApplyReasonIncrOverflow)
325		}
326	}
