328	// TestKVIncrOverflowStuckThenTermConflictReplacesSuffix 回归保障两种既有行为
329	// 相遇时的边界：已提交的 incr 让应用因数值溢出停住后，随后的领导者用更高任期
330	// 合法替换出错条目之后的未提交后缀，不能清掉第一次错误，也不能让应用继续。
331	//
332	// 任期 2 的合法请求匹配前置 idx2（任期 1），用任期 2 的 set count=0（idx3）与
333	// incr count=1（idx4）替换旧 idx3 并追加，leaderCommit=4：
334	//   - 复制层面照常接受（reason ok、无 conflict），任期升到 2、提交位置到 4，
335	//     最终日志保留原已提交 idx1/idx2，旧减一命令消失，新后缀两条完整出现；
336	//   - 尽管新命令格式正确且已复制、已提交，键值表仍只保留最大整数字符串值，
337	//     应用位置仍为 1，逐条结果与最终结果都保留 idx2 的同一溢出原因——不能把
338	//     “已复制、已提交”误当成“已经生效”。
339	func TestKVIncrOverflowStuckThenTermConflictReplacesSuffix(t *testing.T) {
340		initial := overflowSuffixInitial()
341		maxText := strconv.FormatInt(math.MaxInt64, 10)
342	
343		// 起点（不发任何请求）：初始已提交前缀应用后 idx2 溢出停住；未提交的 idx3
344		// 不能提前减一。
345		start := runKV(t, initial)
346		if *start.FinalAppliedIndex != 1 {
347			t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
348		}
349		if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"count": maxText}) {
350			t.Fatalf("initial kv = %v, want only count=%s", start.FinalKV, maxText)
351		}
352		if start.FinalApplyError == nil || start.FinalApplyError.Index != 2 ||
353			start.FinalApplyError.Reason != ApplyReasonIncrOverflow {
354			t.Fatalf("initial applyError = %+v, want index 2 overflow", start.FinalApplyError)
355		}
356		if len(start.FinalLog) != 3 {
357			t.Fatalf("initial log = %d entries, want 3", len(start.FinalLog))
358		}
359	
360		replace := AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 4,
361			Entries: []LogEntry{
362				entry(3, 2, "set count=0"),
363				entry(4, 2, "incr count=1"),
364			}}
365		out := runKV(t, initial, replace)
366		if len(out.Results) != 1 {
367			t.Fatalf("got %d results, want 1", len(out.Results))
368		}
369		result := out.Results[0]
370		// 复制层面：合法后缀替换照常被接受，不能因应用已停住而改变复制裁决。
371		if !result.Accepted || result.Reason != ReasonOK {
372			t.Fatalf("legal suffix replacement should be accepted: %+v", result)
373		}
374		if result.Conflict != nil {
375			t.Fatalf("accepted replacement must not carry a conflict hint: %+v", result.Conflict)
376		}
377		if result.Term != 2 || result.CommittedIndex != 4 {
378			t.Fatalf("result state = term %d ci %d, want term 2 ci 4",
379				result.Term, result.CommittedIndex)
380		}
381		// 应用层面：第一次错误原样保留，应用不能借后缀替换继续。
382		wantOverflowErrorAtIdx2(t, "replace result", result)
383	
384		// 最终日志：已提交的 idx1/idx2 原样保留，旧的减一命令消失，新后缀完整出现。
385		wantLog := []LogEntry{
386			entry(1, 1, "set count="+maxText),
387			entry(2, 1, "incr count=1"),
388			entry(3, 2, "set count=0"),
389			entry(4, 2, "incr count=1"),
390		}
391		if !reflect.DeepEqual(out.FinalLog, wantLog) {
392			t.Fatalf("final log = %+v, want %+v (old decrement must vanish, new suffix intact)",
393				out.FinalLog, wantLog)
394		}
395		if out.FinalTerm != 2 || out.FinalCommittedIndex != 4 {
396			t.Fatalf("final state = term %d ci %d, want term 2 ci 4",
397				out.FinalTerm, out.FinalCommittedIndex)
398		}
399		// 已复制、已提交不等于已生效：计数仍是最大整数字符串，set count=0 未生效。
400		if *out.FinalAppliedIndex != 1 {
401			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
402		}
403		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": maxText}) {
404			t.Fatalf("final kv = %v, want only count=%s (the newly committed suffix must not apply)",
405				kv, maxText)
406		}
407		if out.FinalApplyError == nil || out.FinalApplyError.Index != 2 ||
408			out.FinalApplyError.Reason != ApplyReasonIncrOverflow {
409			t.Fatalf("final applyError = %+v, want the original index 2 overflow error",
410				out.FinalApplyError)
411		}
412	}
