414	// TestKVIncrOverflowStuckRejectsOverwriteOfCommittedErrorEntry 回归保障直接相关
415	// 的边界：应用位置落后于提交位置（停在 1、提交位置已到 4），不代表出错记录
416	// idx2 可以被覆盖。合法后缀替换之后，任期 3 的请求匹配 idx1，却以不同任期改写
417	// 已提交的 idx2（旧任期 1、新任期 3），整条请求必须按“覆盖已提交条目”拒绝，
418	// 并以此区别于上一条被接受的合法后缀替换：拒绝不附带 conflict；较高任期 3 按
419	// 现有规则保留，但日志、提交位置、键值表与 idx2 的第一次溢出错误全部不变。
420	func TestKVIncrOverflowStuckRejectsOverwriteOfCommittedErrorEntry(t *testing.T) {
421		initial := overflowSuffixInitial()
422		maxText := strconv.FormatInt(math.MaxInt64, 10)
423		replace := AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 4,
424			Entries: []LogEntry{
425				entry(3, 2, "set count=0"),
426				entry(4, 2, "incr count=1"),
427			}}
428		// 匹配 idx1，但 idx2 要从任期 1 改成任期 3：idx2 已提交，必须拒绝整条请求。
429		overwrite := AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 4,
430			Entries: []LogEntry{
431				entry(2, 3, "set count=0"),
432				entry(3, 3, "set count=1"),
433				entry(4, 3, "incr count=1"),
434			}}
435	
436		out := runKV(t, initial, replace, overwrite)
437		if len(out.Results) != 2 {
438			t.Fatalf("got %d results, want 2", len(out.Results))
439		}
440		first := out.Results[0]
441		if !first.Accepted || first.Reason != ReasonOK {
442			t.Fatalf("the legal suffix replacement must still be accepted: %+v", first)
443		}
444		if first.Term != 2 || first.CommittedIndex != 4 {
445			t.Fatalf("first result state = term %d ci %d, want term 2 ci 4",
446				first.Term, first.CommittedIndex)
447		}
448		wantOverflowErrorAtIdx2(t, "first result", first)
449	
450		second := out.Results[1]
451		if second.Accepted || second.Reason != ReasonWouldOverwriteCommitted {
452			t.Fatalf("overwriting committed idx2 must be rejected, got %+v", second)
453		}
454		if second.Conflict != nil {
455			t.Fatalf("committed-overwrite rejection must not carry a conflict hint: %+v", second.Conflict)
456		}
457		// 较高任期按现有规则保留，其余状态全部停在第一条请求之后。
458		if second.Term != 3 {
459			t.Fatalf("higher request term must survive the rejection, term = %d, want 3", second.Term)
460		}
461		if second.CommittedIndex != 4 {
462			t.Fatalf("commit moved on rejection: %d, want 4", second.CommittedIndex)
463		}
464		wantOverflowErrorAtIdx2(t, "second result", second)
465	
466		wantLog := []LogEntry{
467			entry(1, 1, "set count="+maxText),
468			entry(2, 1, "incr count=1"),
469			entry(3, 2, "set count=0"),
470			entry(4, 2, "incr count=1"),
471		}
472		if !reflect.DeepEqual(out.FinalLog, wantLog) {
473			t.Fatalf("final log = %+v, want %+v (the rejected overwrite changes nothing)",
474				out.FinalLog, wantLog)
475		}
476		if out.FinalTerm != 3 || out.FinalCommittedIndex != 4 {
477			t.Fatalf("final state = term %d ci %d, want term 3 ci 4",
478				out.FinalTerm, out.FinalCommittedIndex)
479		}
480		if *out.FinalAppliedIndex != 1 {
481			t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
482		}
483		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": maxText}) {
484			t.Fatalf("final kv = %v, want only count=%s", kv, maxText)
485		}
486		if out.FinalApplyError == nil || out.FinalApplyError.Index != 2 ||
487			out.FinalApplyError.Reason != ApplyReasonIncrOverflow {
488			t.Fatalf("final applyError = %+v, want the original index 2 overflow error",
489				out.FinalApplyError)
490		}
491	
492		// 回归保障须能区分两条请求当时的结果（第一条 accepted、第二条 rejected），
493		// 且覆盖已提交的拒绝不输出 conflict 键。
494		encoded, err := json.Marshal(out)
495		if err != nil {
